script:
$since = [datetimeoffset]'2026-10-21T02:30:56Z'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
New-Item -ItemType Directory -Force C:\rpiwin\fw | Out-Null
$n = 'brcmfmac43456-sdio.clm_blob'
if (-not (Test-Path "C:\rpiwin\fw\$n")) {
  Invoke-WebRequest -UseBasicParsing "https://raw.githubusercontent.com/RPi-Distro/firmware-nonfree/trixie/debian/added-firmware/brcm/$n" -OutFile "C:\rpiwin\fw\$n" -TimeoutSec 120
}
"clm blob: " + (Get-Item "C:\rpiwin\fw\$n").Length + " bytes"
$t = $null
for ($i = 0; $i -lt 28; $i++) {
  try {
    $r = Invoke-RestMethod https://api.github.com/repos/xpcpp/Rpi_Win/releases/tags/ci-latest -UseBasicParsing
    $t = [datetimeoffset]$r.assets[0].updated_at
    if ($t -gt $since) { break }
  } catch {}
  Start-Sleep -Seconds 20
}
"release asset updated: $t  (since $since)"
if (-not ($t -gt $since)) { 'CI release not newer yet - aborting'; return }
$dir = 'C:\rpiwin\pkg'
Remove-Item $dir -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory $dir | Out-Null
Invoke-WebRequest -UseBasicParsing 'https://github.com/xpcpp/Rpi_Win/releases/download/ci-latest/bcm2836sdhc-arm64.zip' -OutFile "$dir\pkg.zip" -TimeoutSec 180
Expand-Archive "$dir\pkg.zip" "$dir\x" -Force
$cer = Get-ChildItem "$dir\x" -Recurse -Filter *.cer | Select-Object -First 1
Import-Certificate $cer.FullName -CertStoreLocation Cert:\LocalMachine\Root | Out-Null
Import-Certificate $cer.FullName -CertStoreLocation Cert:\LocalMachine\TrustedPublisher | Out-Null
$inf = Get-ChildItem "$dir\x" -Recurse -Filter sdioprobe.inf | Select-Object -First 1
(pnputil /add-driver $inf.FullName /install | Out-String)
